window.RP_SESSION={"id":"S-7ab1c252d917","messages":[{"id":"RP-0178251","time":"2026-06-26T00:16:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"...\n...\n...","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178252","time":"2026-06-26T00:18:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"아카쿠는 마치 꿈을 꾸는 기분이었다. 사막을 건너면서 만난 도적, 그리고 첫 살인. 비록 미샤가 강요한 행위였지만 분명 그 일을 시도한 것은 아카쿠 스스로임을 부정하지는 않았다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178253","time":"2026-06-26T00:19:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"심지어 이 여정의 끝이 보이는 것처럼 사막의 모래는 점점 사라져가고 푸르름이 돋는 초원이 조금씩 피어나고 있었다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178254","time":"2026-06-26T00:19:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"아카쿠는 사람을 죽였다는 것에 대한 죄책감보다 앞서는 감정이 있었다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178255","time":"2026-06-26T00:20:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"미샤는... 이런 일에 익숙한거야?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178256","time":"2026-06-26T00:20:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"정확하게 말해주세요. 무슨 일을 말하는건가요?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178257","time":"2026-06-26T00:20:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"어... 음...\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178258","time":"2026-06-26T00:20:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"스스로 되물어도 복잡한 감정. 조금은 정리하고 말하는게 나았을지 고민을 잠시 하는 것을 미샤는 묵묵히 기다려줬다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178259","time":"2026-06-26T00:21:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"나쁜 사람들이 있다는 것, 남을 속이는 것, 그리고... 사람을 죽이는 것.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178260","time":"2026-06-26T00:21:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"어쩌면 자신이 아는 것보다 미샤는 더 많은 일을 겪었을지도 모른다고 아카쿠는 생각했다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178261","time":"2026-06-26T00:21:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"왜요. 어떨 것 같아요?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178262","time":"2026-06-26T00:22:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"솔직히 잘 모르겠어. 그냥 그렇지 않을까? 라는 생각이야.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178263","time":"2026-06-26T00:22:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그냥 아카쿠 옆에서 조용히 응원해주고 보살펴주고 마음의 안식처가 되는 그런 순종적인 여성이 아닌 살인귀가 옆에 있다고 생각하니까 무서워요?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178264","time":"2026-06-26T00:22:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"아니, 그렇지는 않아. 미샤가 나에게 나쁜 일을 할 것이라고 생각하지는 않으니까.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178265","time":"2026-06-26T00:23:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"분명 친숙하지는 않은 모습이었지만 미샤는 미샤다. 자신에게 가장 소중하고 가까운 가족.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178266","time":"2026-06-26T00:23:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그리고... 나는 미샤에게 실망하지 않았어. 그러니까 너무 그렇게 날 세우지 않아도 좋다고 생각해.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178267","time":"2026-06-26T00:23:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"이럴 때는 눈치가 빠르네요. 정말...\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178268","time":"2026-06-26T00:24:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"어째서인지 미샤의 걸음이 빨라졌다. 얼굴이 보이지 않는다. 하지만 슬쩍 보이는 귀가 조금 붉은 색을 띄고 있었다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178269","time":"2026-06-26T00:24:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"사실... 조금 후회중이에요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178270","time":"2026-06-26T00:25:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"뭐가?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178271","time":"2026-06-26T00:25:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"이렇게 스카일라에서 나온 일이요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178272","time":"2026-06-26T00:25:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"왜? 조금 불쾌한 일이 있었지만 즐겁게 여행하고 있잖아?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178273","time":"2026-06-26T00:25:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"저희 둘만 있으니까요,\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178274","time":"2026-06-26T00:25:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그게 무슨 이야기야?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178275","time":"2026-06-26T00:25:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"하아....\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178276","time":"2026-06-26T00:25:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"미샤는 한 숨을 크게 내쉬고서 말을 이었다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178277","time":"2026-06-26T00:26:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"아카쿠, 솔직히 말해서 당신은 좋은 사람이에요. 조금은 덤벙대고 엉뚱한 면도 있지만 남들과 곧 잘 지내고 오지랖도 좋은 쪽으로 넓고.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178278","time":"2026-06-26T00:26:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"갑자기 칭찬이야?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178279","time":"2026-06-26T00:26:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"하지만 사람을 너무 잘 믿어요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178280","time":"2026-06-26T00:27:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"로운델에 가면 어떤 일이 있을 것 같아요?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178281","time":"2026-06-26T00:27:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"글쎄? 클램시의 말에 따르면 좋은 사람들이 많이 있다고 들었어.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178282","time":"2026-06-26T00:27:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"아니요, 그럴리 없죠.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178283","time":"2026-06-26T00:28:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"분명 멸시받을거에요. 길을 가다가 이유 없이 욕을 먹고 침을 맞고. 조금 으슥한 곳에 가면 두들겨 맞기도 하고.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178284","time":"2026-06-26T00:28:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"어... 음...\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178285","time":"2026-06-26T00:29:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"아카쿠는 미샤의 이야기를 듣고 어쩌면 자신이 너무 무심하지 않았나 싶었다. 인간 사이에 들어간 드라고니안 한명. 과연 미샤의 말대로 좋은 꼴만 보기는 힘들 것이다. 그리고 그 사실을 생각하자 아카쿠의 마음이 조금은 무거워졌다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178286","time":"2026-06-26T00:29:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그렇게 살아온거구나?\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178287","time":"2026-06-26T00:29:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"맞아요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178288","time":"2026-06-26T00:29:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"사실 저는 아카쿠의 가문이 정말 싫었어요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178289","time":"2026-06-26T00:30:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"드라고니안들만 득실득실하고. 저는 그저 미운 인간 한 명. 보이지 않는 곳에서 생각보다 많은 괴롭힘을 당했으니까요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178290","time":"2026-06-26T00:30:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178291","time":"2026-06-26T00:30:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"과연 아카쿠는 이 사실을 모르고 있을까? 라고 하면 그렇지는 않을 것이다. 다만 기억에서 잊고 현실에서 눈을 돌린 비겁한 행위일지도 모른다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178292","time":"2026-06-26T00:31:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그 덕에 뒷골목이 좋았어요. 여러 인종이 모이고, 조금 위험하기는 하지만 오히려 그 덕에 제 앞가림만 할 줄 알면 지내기 쉽고.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178293","time":"2026-06-26T00:31:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"어...\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178294","time":"2026-06-26T00:31:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"부담 주려는건 아니에요. 아니, 부담이어도 그냥 들어요. 저도 제 생각을 말할 필요가 있을 것 아니에요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178295","time":"2026-06-26T00:32:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"아카쿠는 잠잠히 듣기로 했다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178296","time":"2026-06-26T00:33:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"저는 당신이 생각하는 것보다 더 험하게 살았을거라고 생각해요. 드루이드의 깨달음을 얻기 위해 떠난 여행에서 일어난 일들, 옛날 당신을 노리던 사람들을 처리하기도 했고.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178297","time":"2026-06-26T00:33:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"마냥 착하고 순종적인 애완인간 미샤는 없어진지 오래에요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178298","time":"2026-06-26T00:33:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그건 알고 있어.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178299","time":"2026-06-26T00:33:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"퍽이나.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178300","time":"2026-06-26T00:34:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"미샤는 뭐가 불만인지 꿍얼꿍얼 거리고 있었다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178301","time":"2026-06-26T00:34:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그래도 갈래.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178302","time":"2026-06-26T00:34:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"나도 조금 부담을 주는 이야기를 할거야.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178303","time":"2026-06-26T00:34:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"네가 힘들었던 만큼 나도 힘들어볼게.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178304","time":"2026-06-26T00:34:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"네가 느낌 외로움을 나도 느껴볼게.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178305","time":"2026-06-26T00:35:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"네가 살던 세계는 솔직히 가기 힘들 것 같기는 하지만... 하지만 그 죄는 같이 짊어질게.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178306","time":"2026-06-26T00:35:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"나, 라이아흐 아카쿠는 라이아흐 미샤의 곁에 있을거야.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178307","time":"2026-06-26T00:35:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"지켜볼게요.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178308","time":"2026-06-26T00:35:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"\"그래.\"","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178309","time":"2026-06-26T00:35:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"아카쿠는 칵칵칵! 하고 웃었다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178310","time":"2026-06-26T00:36:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"미샤는 웃음 소리를 내지는 않았지만 분명 웃고 있었다.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178311","time":"2026-06-26T00:36:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"골기아로 향하는 여정은 어떤 일이 일어날지 모를 그런 여정이지만.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178312","time":"2026-06-26T00:36:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"둘이 같이 있다면 어떻게든 되겠지.","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178313","time":"2026-06-26T00:36:00+09:00","room":"RP","name":"아카쿠 / 미샤","profile":"GM","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-96ab98d2591c","P-41ba4c5736e6"]},{"id":"RP-0178314","time":"2026-06-26T00:36:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]}]};
